41	/// A [`GlobSet`] pair implementing npm/pnpm/Yarn-style workspace glob
42	/// negation. `globset`'s `GlobSetBuilder` has no negation concept of its
43	/// own -- a pattern with a leading `!` is just another literal
44	/// positive-match glob to it, so `!packages/excluded` compiles into a glob
45	/// that matches paths literally starting with the character `!`, which
46	/// never matches any real path. That silently no-ops the negation instead
47	/// of excluding anything.
48	///
49	/// A path is admitted only when it matches at least one `positive` pattern
50	/// and matches none of the `negative` (`!`-stripped) patterns -- mirroring
51	/// how npm/pnpm/Yarn actually resolve workspace globs (later patterns can
52	/// negate earlier ones; a leading `!` excludes). A positive-only pattern
53	/// list behaves exactly as a plain [`GlobSet`] would. An all-negative list
54	/// has an empty positive set, so `is_match` is always `false` -- there is no
55	/// positive baseline for the negation to carve an exclusion out of.
56	pub(crate) struct NegatableGlobSet {
57	    positive: GlobSet,
58	    negative: GlobSet,
59	}
60	
61	impl NegatableGlobSet {
62	    pub(crate) fn is_match(&self, path: &Path) -> bool {
63	        self.positive.is_match(path) && !self.negative.is_match(path)
64	    }
65	
66	    pub(crate) fn empty() -> Self {
67	        NegatableGlobSet {
68	            positive: GlobSet::empty(),
69	            negative: GlobSet::empty(),
70	        }
71	    }
72	}
