74	/// Builds a [`NegatableGlobSet`] from a list of glob strings, matched with
75	/// `literal_separator(true)` semantics (`*` does not cross `/`; `**` does)
76	/// against forward-slash-normalized, workspace-relative paths. An entry
77	/// with a leading `!` is treated as a negative (exclusion) pattern -- see
78	/// [`NegatableGlobSet`].
79	///
80	/// An entry that fails to compile is an error: skipping it would leave an exclusion or a
81	/// member unapplied and change which packages the workspace admits.
82	pub(crate) fn build_globset(entries: &[String]) -> Result<NegatableGlobSet, globset::Error> {
83	    let mut positive = GlobSetBuilder::new();
84	    let mut negative = GlobSetBuilder::new();
85	    for entry in entries {
86	        let (builder, pattern) = match entry.strip_prefix('!') {
87	            Some(rest) => (&mut negative, rest),
88	            None => (&mut positive, entry.as_str()),
89	        };
90	        builder.add(GlobBuilder::new(pattern).literal_separator(true).build()?);
91	    }
92	    Ok(NegatableGlobSet {
93	        positive: positive.build()?,
94	        negative: negative.build()?,
95	    })
96	}
