120	impl Membership {
121	    /// `rel` must be a workspace-relative, forward-slash-normalized path.
122	    /// `is_root` is true exactly when `rel == Path::new(".")`.
123	    pub(crate) fn admits(&self, rel: &Path, is_root: bool) -> bool {
124	        if is_root && self.hybrid_root {
125	            return true;
126	        }
127	        if self.exclude.is_match(rel) {
128	            return false;
129	        }
130	        match &self.members {
131	            None => true,
132	            Some(members) => members.is_match(rel),
133	        }
134	    }
