138	    pub(crate) fn admits_explicitly(&self, rel: &Path, is_root: bool) -> bool {
139	        if is_root && self.hybrid_root {
140	            return true;
141	        }
142	        match &self.members {
143	            Some(members) => !self.exclude.is_match(rel) && members.is_match(rel),
144	            None => false,
145	        }
146	    }
