197	/// Reads the workspace membership declared by the root manifest.
198	///
199	/// A missing manifest, or one with no workspace table or no `members` key, restricts nothing. A manifest that cannot be
200	/// read or parsed, or whose `members`/`exclude` is not an array of valid globs, is an error naming the file: guessing
201	/// "every directory" there would turn vendored copies and excluded crates into releasable packages.
202	pub(crate) fn read_membership(root: &Path, spec: &MembershipSpec) -> Result<Membership, LocateError> {
203	    let path = root.join(spec.manifest_file_name);
204	    let Some(content) = read_root_manifest(&path)? else {
205	        return Ok(Membership::unrestricted());
206	    };
207	    let doc = content
208	        .parse::<toml_edit::DocumentMut>()
209	        .map_err(|error| parse_error(&path, error.to_string()))?;
210	
211	    let mut cursor: Option<&toml_edit::Item> = doc.get(spec.table_path[0]);
212	    for key in &spec.table_path[1..] {
213	        cursor = cursor.and_then(|c| c.get(*key));
214	    }
215	
216	    let hybrid_root = doc.get(spec.owner_key).is_some() && cursor.is_some();
217	    let Some(workspace) = cursor else {
218	        return Ok(Membership {
219	            members: None,
220	            exclude: NegatableGlobSet::empty(),
221	            hybrid_root,
222	        });
223	    };
224	    let table = spec.table_path.join(".");
225	    if workspace.as_table_like().is_none() {
226	        return Err(invalid_membership(&path, format!("`{table}` must be a table")));
227	    }
228	    let globs = |key: &str| -> Result<Option<NegatableGlobSet>, LocateError> {
229	        let Some(item) = workspace.get(key) else {
230	            return Ok(None);
231	        };
232	        let full_key = format!("{table}.{key}");
233	        let entries = parse_toml_string_array(item)
234	            .ok_or_else(|| invalid_membership(&path, format!("`{full_key}` must be an array of strings")))?;
235	        compile_globs(&path, &full_key, &entries).map(Some)
236	    };
237	    Ok(Membership {
238	        members: globs("members")?,
239	        exclude: globs("exclude")?.unwrap_or_else(NegatableGlobSet::empty),
240	        hybrid_root,
241	    })
242	}
