            None => true,
            Some(globs) => globs.is_match(rel),
        }
    }

    /// See [`Membership::admits_explicitly`]: `None` globs never counts here.
    pub(crate) fn admits_explicitly(&self, rel: &Path, is_root: bool) -> bool {
        if is_root && self.hybrid_root {
