9	/// Finds the root between `start` and its Git toplevel (never above it): the nearest
10	/// workspace marker, else the outermost package manifest so vendored packages can't shadow it.
11	///
12	/// The toplevel comes from `git rev-parse --show-toplevel` (via `runner`), not a hand-rolled
13	/// walk for a `.git` entry -- `git` alone honors `GIT_DIR`/`GIT_WORK_TREE`/
14	/// `GIT_CEILING_DIRECTORIES` the way every other Git-aware tool does.
15	pub fn find_workspace_root(start: &Path, runner: &dyn CommandRunner) -> Result<PathBuf, LocateError> {
16	    let canonical = dunce::canonicalize(start).unwrap_or_else(|_| start.to_path_buf());
17	    let toplevel = GitAccess::new(&canonical, runner).toplevel().map_err(|e| match &e {
18	        VcsError::Git(message) if message.to_lowercase().contains("not a git repository") => {
19	            LocateError::NotAGitRepository {
20	                start: start.to_path_buf(),
21	            }
22	        }
23	        _ => LocateError::from(e),
24	    })?;
25	    let range = || canonical.ancestors().take_while(|dir| dir.starts_with(&toplevel));
26	    for dir in range() {
27	        if is_workspace_root(dir)? {
28	            return Ok(dir.to_path_buf());
29	        }
30	    }
31	    let mut outermost = None;
32	    for dir in range() {
33	        if is_package_root(dir)? {
34	            outermost = Some(dir);
35	        }
36	    }
37	    outermost
38	        .map(Path::to_path_buf)
39	        .ok_or_else(|| LocateError::WorkspaceRootNotFound {
40	            start: start.to_path_buf(),
41	            toplevel: toplevel.clone(),
42	        })
43	}
