45	/// Loads `dir/Cargo.toml` as a TOML document, or `None` if it does not exist. A manifest that cannot be read or
46	/// parsed is an error: skipping it would let the search settle on a different root.
47	fn cargo_document(dir: &Path) -> Result<Option<toml_edit::DocumentMut>, LocateError> {
48	    let path = dir.join("Cargo.toml");
49	    read_root_manifest(&path)?
50	        .map(|content| {
51	            content
52	                .parse::<toml_edit::DocumentMut>()
53	                .map_err(|error| parse_error(&path, error.to_string()))
54	        })
55	        .transpose()
56	}
57	
58	fn path_exists(path: &Path) -> Result<bool, LocateError> {
59	    callisto_model::strict_fs::exists(path).map_err(|error| LocateError::ManifestReadError {
60	        path: path.to_path_buf(),
61	        message: error.to_string(),
62	    })
63	}
64	
65	/// True when `key` names a table declared with its own header (`[key]`), not a table that
66	/// exists only implicitly as a dotted-key parent (e.g. `[key.sub]` alone does not count) or
67	/// text that merely mentions the name inside a comment.
68	fn has_explicit_table(doc: &toml_edit::DocumentMut, key: &str) -> bool {
69	    doc.get(key)
70	        .and_then(|item| item.as_table())
71	        .is_some_and(|t| !t.is_implicit())
72	}
73	
74	/// A single-package repository root: `Cargo.toml` with `[package]`, `package.json`, or `pyproject.toml`.
75	fn is_package_root(dir: &Path) -> Result<bool, LocateError> {
76	    if cargo_document(dir)?.is_some_and(|doc| has_explicit_table(&doc, "package")) {
77	        return Ok(true);
78	    }
79	    Ok(path_exists(&dir.join("package.json"))? || path_exists(&dir.join("pyproject.toml"))?)
80	}
81	
82	fn is_workspace_root(dir: &Path) -> Result<bool, LocateError> {
83	    if cargo_document(dir)?.is_some_and(|doc| has_explicit_table(&doc, "workspace")) {
84	        return Ok(true);
85	    }
86	
87	    let pkg_json = dir.join("package.json");
88	    if let Some(content) = read_root_manifest(&pkg_json)? {
89	        let value = serde_json::from_str::<serde_json::Value>(&content)
90	            .map_err(|error| parse_error(&pkg_json, error.to_string()))?;
91	        if value.get("workspaces").is_some() {
92	            return Ok(true);
93	        }
94	    }
95	
96	    Ok(path_exists(&dir.join("pnpm-workspace.yaml"))? || dir.join(".moon").is_dir())
97	}
