1	use std::collections::BTreeSet;
2	use std::path::{Path, PathBuf};
3	
4	use callisto_model::{workspace_relative, Ecosystem, PackageId, ProjectRoot};
5	use ignore::WalkBuilder;
6	
7	use crate::locate::membership;
8	use crate::locate::{find_workspace_root, LocateError, ProjectLocator};
9	
10	pub struct IgnoreWalkLocator {
11	    root: PathBuf,
12	    skip: BTreeSet<&'static str>,
13	}
14	
15	impl IgnoreWalkLocator {
16	    pub fn new(root: &Path) -> Self {
17	        let mut skip = BTreeSet::new();
18	        skip.insert("target");
19	        skip.insert("node_modules");
20	        skip.insert(".git");
21	        skip.insert(".moon");
22	        skip.insert("dist");
23	
24	        let canonical = dunce::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
25	        IgnoreWalkLocator { root: canonical, skip }
26	    }
27	
28	    pub fn discover(start: &Path, runner: &dyn callisto_model::CommandRunner) -> Result<Self, LocateError> {
29	        let root = find_workspace_root(start, runner)?;
30	        Ok(Self::new(&root))
31	    }
32	}
33	
34	impl ProjectLocator for IgnoreWalkLocator {
35	    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError> {
36	        Ok(self.projects_and_platform_candidates()?.0)
37	    }
38	
39	    fn projects_and_platform_candidates(&self) -> Result<(Vec<ProjectRoot>, Vec<ProjectRoot>), LocateError> {
40	        let mut results = Vec::new();
41	        let mut platform_candidates = Vec::new();
42	        let cargo_membership = membership::read_cargo_membership(&self.root)?;
43	        let npm_membership = membership::read_npm_membership(&self.root)?;
44	        let python_membership = membership::read_python_membership(&self.root)?;
45	        let walker = WalkBuilder::new(&self.root)
46	            .hidden(true)
47	            .git_ignore(true)
48	            .parents(false)
49	            .max_depth(Some(32))
50	            // Symlinked package directories (e.g. vendor-link style monorepos) are a
51	            // supported workspace pattern -- discovery follows them deliberately. The
52	            // existing max_depth(32) cap already bounds a symlink cycle from hanging.
53	            .follow_links(true)
54	            .filter_entry({
55	                let skip = self.skip.clone();
56	                move |entry| {
57	                    if let Some(name) = entry.file_name().to_str() {
58	                        if skip.contains(name) {
59	                            return false;
60	                        }
61	                    }
62	                    true
63	                }
64	            })
65	            .build();
66	
67	        for entry_res in walker {
68	            let entry = entry_res.map_err(|e| LocateError::Walk {
69	                path: self.root.clone(),
70	                message: e.to_string(),
71	            })?;
72	
73	            let path = entry.path();
74	            if !path.is_dir() {
75	                continue;
76	            }
77	
78	            let rel = to_workspace_relative(path, &self.root)?;
79	            let is_root = rel == Path::new(".");
80	            let admits = |ecosystem: Ecosystem| match ecosystem {
81	                Ecosystem::Cargo => cargo_membership.admits(&rel, is_root),
82	                Ecosystem::Npm => npm_membership.admits(&rel, is_root),
83	                Ecosystem::Pypi => python_membership.admits(&rel, is_root),
84	                _ => false,
85	            };
86	            // Own-path check for a *failed* manifest: only a real, explicit members/workspaces
87	            // match counts -- the admit-all fallback (no restriction present, e.g. because this
88	            // very manifest is the one that failed to parse) must not count as membership.
89	            let admits_explicitly = |ecosystem: Ecosystem| match ecosystem {
90	                Ecosystem::Cargo => cargo_membership.admits_explicitly(&rel, is_root),
91	                Ecosystem::Npm => npm_membership.admits_explicitly(&rel, is_root),
92	                Ecosystem::Pypi => python_membership.admits_explicitly(&rel, is_root),
93	                _ => false,
94	            };
95	
96	            // First pass: read and parse every canonical manifest present in this
97	            // directory, so a parse failure below can check whether a *sibling*
98	            // manifest here was admitted, not only its own ecosystem's membership.
99	            let mut parsed: Vec<(Ecosystem, String, callisto_manifests::ManifestIdentity)> = Vec::new();
100	            let mut failures: Vec<(PathBuf, ManifestFailure)> = Vec::new();
101	            for ecosystem in Ecosystem::CANONICAL {
102	                // Every `Ecosystem::CANONICAL` member has a canonical
103	                // manifest format by construction -- see its doc comment.
104	                let format = ecosystem
105	                    .canonical_manifest_format()
106	                    .expect("CANONICAL ecosystems always have a canonical manifest format");
107	                let manifest_path = path.join(format.file_name());
108	                let content = match callisto_model::strict_fs::read_optional(&manifest_path) {
109	                    Ok(Some(content)) => content,
110	                    Ok(None) => continue,
111	                    Err(e) => {
112	                        failures.push((manifest_path, ManifestFailure::Unreadable(e.to_string())));
113	                        continue;
114	                    }
115	                };
116	                match callisto_manifests::read_identity(format, &content, &manifest_path) {
117	                    Ok(identity) => parsed.push((ecosystem, content, identity)),
118	                    Err(e) => failures.push((manifest_path, ManifestFailure::Unparseable(e.to_string()))),
119	                }
120	            }
121	
122	            // Explicit only, like `self_admitted` below -- a sibling that's merely admitted by
123	            // the fallback admit-all (no restriction present for that ecosystem) doesn't make
124	            // this directory a real, deliberate workspace member; only a genuine members/
125	            // workspaces match does.
126	            let any_sibling_admitted = parsed
127	                .iter()
128	                .any(|(ecosystem, _, identity)| identity.name.is_some() && admits_explicitly(*ecosystem));
129	
130	            for (manifest_path, failure) in failures {
131	                // Determine which ecosystem this failed manifest belongs to from its
132	                // file name, to check its own membership independent of any sibling.
133	                let ecosystem = Ecosystem::CANONICAL.into_iter().find(|eco| {
134	                    eco.canonical_manifest_format()
135	                        .is_some_and(|f| Some(f.file_name()) == manifest_path.file_name().and_then(|n| n.to_str()))
136	                });
137	                let self_admitted = ecosystem.is_some_and(admits_explicitly);
138	                if self_admitted || any_sibling_admitted {
139	                    return Err(match failure {
140	                        ManifestFailure::Unreadable(message) => LocateError::ManifestReadError {
141	                            path: manifest_path,
142	                            message,
143	                        },
144	                        ManifestFailure::Unparseable(message) => LocateError::ManifestParseError {
145	                            path: manifest_path,
146	                            message,
147	                        },
148	                    });
149	                }
150	                eprintln!("{}", unparseable_manifest_warning(&manifest_path, &failure));
151	            }
152	
153	            for (ecosystem, content, identity) in parsed {
154	                let Some(name) = identity.name else {
155	                    continue;
156	                };
157	
158	                // A private, versionless root package.json (standard npm/pnpm workspace-root
159	                // layout, e.g. `@changesets/cli`) declares a name only to hold `workspaces`; it
160	                // is never itself a released package, so it never becomes a project.
161	                if is_root
162	                    && ecosystem == Ecosystem::Npm
163	                    && identity.version.is_none()
164	                    && callisto_manifests::npm_declares_private(&content)
165	                {
166	                    continue;
167	                }
168	
169	                let admitted = admits(ecosystem);
170	                let id = PackageId::parse(&name).unwrap_or_else(|_| PackageId::Bare(name.clone()));
171	                let project = ProjectRoot {
172	                    id,
173	                    path: rel.clone(),
174	                    ecosystem,
175	                };
176	                if admitted {
177	                    reject_symlinked_package(&self.root, &rel)?;
178	                    results.push(project);
179	                } else if ecosystem == Ecosystem::Npm && callisto_manifests::npm_role_from_source(&content).is_some() {
180	                    reject_symlinked_package(&self.root, &rel)?;
181	                    platform_candidates.push(project);
182	                }
183	            }
184	        }
185	
186	        results.sort_by(|a, b| (&a.path, a.ecosystem).cmp(&(&b.path, b.ecosystem)));
187	        platform_candidates.sort_by(|a, b| a.path.cmp(&b.path));
188	        Ok((results, platform_candidates))
189	    }
190	}
191	
192	/// Git cannot stage a path beneath a symbolic link, so a package there could be edited on disk but never committed.
193	/// Discovery follows links only so that it can name such a package here instead of silently skipping it.
194	fn reject_symlinked_package(root: &Path, rel: &Path) -> Result<(), LocateError> {
195	    let mut current = root.to_path_buf();
196	    for component in rel.components() {
197	        current.push(component);
198	        let metadata = std::fs::symlink_metadata(&current).map_err(|error| LocateError::Walk {
199	            path: current.clone(),
200	            message: error.to_string(),
201	        })?;
202	        if metadata.file_type().is_symlink() {
203	            return Err(LocateError::SymlinkedPackage {
204	                path: rel.to_path_buf(),
205	            });
206	        }
207	    }
208	    Ok(())
209	}
210	
211	/// Why a manifest present in a directory could not be turned into an identity.
212	enum ManifestFailure {
213	    Unreadable(String),
214	    Unparseable(String),
215	}
216	
217	/// Warning text for a manifest that fails to read or parse but isn't a workspace member (its own
218	/// ecosystem doesn't admit it, and it shares no directory with an admitted manifest) --
219	/// tested directly, since `eprintln!` output can't be captured from inside discovery.
220	fn unparseable_manifest_warning(path: &Path, failure: &ManifestFailure) -> String {
221	    match failure {
222	        ManifestFailure::Unreadable(message) => {
223	            format!("warning: failed to read manifest `{}`: {message}", path.display())
224	        }
225	        ManifestFailure::Unparseable(message) => {
226	            format!("warning: failed to parse manifest `{}`: {message}", path.display())
227	        }
228	    }
229	}
230	
231	fn to_workspace_relative(path: &Path, root: &Path) -> Result<PathBuf, LocateError> {
232	    if !path.starts_with(root) {
233	        return Err(LocateError::OutsideWorkspaceRoot {
234	            path: path.to_path_buf(),
235	            root: root.to_path_buf(),
236	        });
237	    }
