    #[test]
    fn admits_all_npm_candidates_when_no_workspaces_field_and_no_pnpm_yaml() {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path();
        std::fs::write(root.join("package.json"), r#"{"name":"root"}"#).unwrap();
